// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(address caller, uint256 amount) internal {
        vm.assume(caller != address(0));
        caller = c.owner();
        caller = address(this);
        bool reverted;
        try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == false);
    }

    function testFuzz_run(address caller, uint256 amount) public {
        _run(caller, amount);
    }

    receive() external payable {}
}
